{
  "table": {
    "name": "tags",
    "purpose": "The tag directory of a Stack-Exchange-style Q&A site: one row per tag, giving its label, how many questions carry it, and links to the posts containing its excerpt and wiki descriptions. The tag vocabulary (2sls, ab-test, glmm, overdispersion, rjags, stratification, joint-distribution, polling) indicates a statistics/Q&A site, consistent with a Cross Validated (stats.stackexchange.com) data dump alongside the posts, users, votes, comments, badges, postHistory and postLinks tables."
  },
  "columns": {
    "Count": {
      "role": "numeric",
      "name": "tag usage count",
      "description": "Number of questions on the site tagged with this tag. Ranges from 1 to 7244 with a median of 29: most tags are used on a handful of questions while a few are very common. This is the standard 'Count' column of the Stack Exchange Tags table (count of questions carrying the tag).",
      "status": "resolved"
    },
    "ExcerptPostId": {
      "role": "foreign_key",
      "name": "excerpt post id",
      "description": "Foreign key to posts.Id pointing at the post that holds the tag's short excerpt (usage summary). Unique per tag (one-to-one with posts) and null for ~42% of tags, i.e. tags that have no excerpt written yet.",
      "status": "resolved"
    },
    "Id": {
      "role": "identifier",
      "name": "tag id",
      "description": "Primary key of the tags table; unique identifier for each tag. Values run 1-1869 for 1032 rows, so some ids are absent (deleted or merged tags).",
      "status": "resolved"
    },
    "TagName": {
      "role": "identifier",
      "name": "tag name",
      "description": "The tag's display label: a unique, lowercase, hyphenated keyword such as 'glmm', 'ab-test', 'stratification' or 'joint-distribution'. One row per tag name.",
      "status": "resolved"
    },
    "WikiPostId": {
      "role": "foreign_key",
      "name": "wiki post id",
      "description": "Foreign key to posts.Id pointing at the post that holds the tag's full wiki (detailed description). Unique per tag (one-to-one with posts) and null for the same ~42% of tags that lack an excerpt. WikiPostId is consistently ExcerptPostId - 1 (e.g. 65333/65334, 62342/62343), showing the wiki and excerpt posts are created together as a consecutive pair.",
      "status": "resolved"
    }
  }
}
